TLM.f("Sancti/12-16",{"officium":"S. Eusebii Episcopi et Martyris","rule":["vide C2b;","Gloria"],"fallback":"Commune/C2b","from":{"Introitus":"Commune/C2b","Lectio":"Commune/C2b","Graduale":"Commune/C2b","Tractus":"Commune/C2b","Evangelium":"Commune/C2b","Offertorium":"Commune/C2b","Communio":"Commune/C2b"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:84; 3:87"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."},{"k":"ref","la":"Dan 3:57"},{"k":"text","la":"Benedícite, ómnia ópera Dómini, Dómino: laudáte et superexaltáte eum in sǽcula."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes Dei, benedícite Dóminum: sancti et húmiles corde, laudáte Deum."}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Eusébii Mártyris tui atque Pontíficis ánnua sollemnitáte lætíficas: concéde propítius; ut, cujus natalítia cólimus, de ejúsdem étiam protectióne gaudeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 1:3-7"},{"k":"text","la":"Fratres: Benedíctus Deus et Pater Dómini nostri Jesu Christi, Pater misericordiárum, et Deus totíus consolatiónis, qui consolátur nos in omni tribulatióne nostra: ut possímus et ipsi consolári eos, qui in omni pressúra sunt, per exhortatiónem, qua exhortámur et ipsi a Deo. Quóniam sicut abúndant passiónes Christi in nobis: ita et per Christum abúndat consolátio nostra. Sive autem tribulámur pro vestra exhortatióne et salúte, sive consolámur pro vestra consolatióne, sive exhortámur pro vestra exhortatióne et salúte, quæ operátur tolerántiam earúndem passiónum, quas et nos pátimur: ut spes nostra firma sit pro vobis: sciéntes, quod, sicut sócii passiónum estis, sic éritis et consolatiónis: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hic est Sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum."},{"k":"text","la":"Et constituísti eum super ópera mánuum tuárum, Dómine.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:24-27"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si quis vult post me veníre, ábneget semetípsum, et tollat crucem suam, et sequátur me. Qui enim voluerit ánimam suam salvam fácere, perdet eam: qui autem perdíderit ánimam suam propter me, invéniet eam. Quid enim prodest hómini, si mundum univérsum lucrétur, ánimæ vero suæ detriméntum patiátur? Aut quam dabit homo commutatiónem pro ánima sua? Fílius enim hóminis ventúrus est in glória Patris sui cum Angelis suis: et tunc reddet unicuíque secúndum ópera ejus."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicáta sanctífica: et, intercedénte beáto Eusébio Mártyre tuo atque Pontífice, per éadem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáto Eusébio Mártyre tuo atque Pontífice, coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"002aa5549dabb5c9":{"t":"<i>Pomolimo se</i>.\nBože koji nas razveseljuješ svetkovinom blaženoga Euzebija tvoga mučenika i biskupa, daj milostivo da se radujemo zaštiti onoga kojeg rođendan slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, preblagi Bože, koji nais razveseljuješ svečanom godišnjicom blaženoga I., .Tvoga mučenika i biskupa, da se radujemo zaštiti onoga, kojega rođeni dan slavimo. Po G. n.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"98a3271a716eb33d":{"t":"Posveti, Gospodine, darove tebi prikazane i njima umilostivljen pogledaj na nas po zagovoru blaženog Euzebija tvoga mučenika i biskupa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, Gospodine, namijenjene Ti darove, te njima umilostivljen, a zagovorom blaženoga I., Tvoga mučenika i biskupa, pogledaj na nas. Po G. n.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"0a4660f78e7936b9":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, ova Pričest očisti od opačina i učini po zagovoru blaženog Euzebija, tvoga mučenika i biskupa dionicima nebeske pomoći.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da nas ova pričest očisU od grijeha i zagovorom blaženoga I., Tvoga mučenika i biskupa, učini dionicima nebeskog blaženstva. Po G. n.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"6fc068ff728b99e0":{"t":"Dn 3, 84 et 87, Dn 3, 57\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga! (Dn 3, 57) Blagoslivljajte, sva djela Gospodnja, Gospodina, hvalite i uzvisujte ga dovijeka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dn 3, 84 i 87) Svećenici Božji, blagoslivljajte Gospodina! Sveti i ponizni, srcem, hvalite Boga!","kn":"(Dan. 3, 84, 87). Blagosivajte Gospodina, svećenici Božji; hvalite Boga, sveti i ponizni srcem. (Dani. 3, 57) Blagosivajte Gospodina, sva djela Gospodnja, slavite ga i veličajte, u vjekove! Slava Ocu . . . Blagosivajte . . .","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"2ce338a966794640":{"t":"2 Kor 1, 3-7\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, blagoslovljen Bog i Otac našega Gospodina Isusa Krista, Otac milosrđa i Bog pune utjehe, koji nas tješi u svakoj nevolji što nas zadesi, da bismo one koji se nalaze u bilo kojoj stisci mogli tješiti onom utjehom što smo je mi sami primili od Boga. I kao što su za nas plodne Kristove patnje, tako po Kristu dobivamo obilnu utjehu. Ako štogod trpimo, to vama biva na utjehu i spas. Ako primamo utjehe, i vama je na utjehu, ako nas ohrabruju, to je za vašu jakost i spas. To vam omogućuje da strpljivo podnosite iste patnje što ih i mi podnosimo. Tome se čvrsto za vas nadamo uvjereni, da ćete kao što ste bili sudionici u patnjama, tako biti i u utjesi u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 1, '3-7). Braćo! Blagoslovljen Bog i Otac Gospodina našega Isusa Krista, Otac milosrđa i Bog svake utjehe, koji nas tješi u svakoj našoj nevolji, da one, koji se nalaze u bilo kojoj stisci, možemo tješiti onom utjehom, kojom i nas same tješi Bog. Jer kao što u nama obiluju Kristove patnje, tako po Kristu obiluje 1 naša utjeha. Bilo da trpimo, to je za vašu utjehu i spas, bUo da se tješimo, za vašu je utjehu, bilo da nas hrabre, vama je na jakost i spas. To daje, da strpljivo podnosite iste patnje, koje podnosimo i mi. To se čvrsto za vas nadamo znajući, da kao što ste bili sudionici u patnjama, da ćete tako biti i u utjehi u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"6dc7e0e935655ab8":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je svećenik koga je okrunio Gospodin. <i>Aleluja</i>.","kn":"(Ps. 8, 6-7). Okrunio si ga slavom i čašću i postavio si ga nad sva djela tvoja. Gospodine!\n\nAleluja, aleluja! Ovo je svećenik, koga je okrunio Gospođin, aleluja!","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"3068222c7b7795b6":{"t":"Mt 16, 24-27\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Ako tko hoće da ide za mnom, neka se odreče sebe, uzme svoj križ i pođe za mnom. Tko hoće spasiti svoj život izgubit će ga, a tko izgubi svoj život radi mene naći će ga. Što koristi čovjeku, ako dobije čitav svijet, a izgubi svoju dušu? Kakvu će zamjenu čovjek dati za svoju dušu? Sin će Čovječji doći u slavi svoga Oca s anđelima, i tada će svakome naplatiti po njegovim djelima.","kn":"t Slijedi sv. evanđelje po Matejii (16, 24-27). U ono vrijeme reče Isus svojim učenicima: Ako tko hoće da ide za mnom, neka se odreče samoga sebe, uzme svoj križ i slijedi me. Tko hoće da spasi svoj život,, izgubit će ga, a tko izgubi svoj život radi mene, naći će ga. Jer što koristi čovjeku, ako dobije sav svijet, a izgubi svoju dušu? Ili kakvu će zamjenu dati čovjek za svoju dušu? Jer će Sin čovječji doći u slavi svoga Oca sa svojim anđelima i tada će svakomu platiti po njegovim djelima. ^","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"c1545941e0b9c017":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja.","kn":"(Ps. 88, 21, 22). Izabrao sam Davida za slugu svoga i pomazao sam ga mojim svetim uuem. Moja će ga ruka i mišica će ga moja krijepiti, aleluja. .","knRef":"Kniewald 1942, str. 560–561 (snimka 281) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f865cc96d8c6795d":{"t":"Ps 20, 4\nOkrunio si ga, Gospodine, krunom od dragoga kamenja.","kn":"(Ps. 20, 4). Postavio si, Gospoidine, na glavu njegovu krunu od dragoga kamenja.","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"}}});
